import{cycleState,manualStep,DURATION,routePlan}from'./bus-core.mjs';
import{BusAudio}from'./bus-audio.mjs';
const root=document.querySelector('[data-tool="yutong"]');
if(root){const $=s=>root.querySelector(s),start=$('[data-bus-start]'),pause=$('[data-bus-pause]'),stop=$('[data-bus-stop]'),manual=$('#bus-manual'),controls=$('[data-manual-controls]'),rpm=$('#bus-rpm'),gas=$('#bus-throttle'),brake=$('#bus-brake'),volume=$('#bus-volume'),condition=$('#bus-condition'),loop=$('#bus-loop'),status=$('[data-bus-status]'),target=$('#bus-target'),style=$('#bus-driving-style'),shiftMode=$('#bus-shift-mode'),gearDown=$('[data-gear-down]'),gearUp=$('[data-gear-up]');let forcedGear=null;const options=()=>({target:Number(target.value),style:style.value}),duration=()=>routePlan(Number(target.value),style.value).total;let audio=null,playing=false,paused=false,elapsed=0,last=0,frame=0,token=0,state=cycleState(0),held={gas:0,brake:0};
function display(){ $('[data-rpm]').textContent=String(Math.round(state.rpm));$('[data-speed]').textContent=state.speed.toFixed(1);$('[data-gear]').textContent=(manual.checked&&forcedGear!==null?'M':'D')+state.gear;$('[data-frequency]').textContent=state.frequency.toFixed(1)+' Hz';$('[data-phase]').textContent=playing?(manual.checked?state.phase:state.done?'行車完成，維持怠速':state.phase):paused?'已暫停':'引擎關閉';$('[data-elapsed]').textContent=manual.checked?'手動行車':elapsed.toFixed(1)+' / '+duration().toFixed(1).replace(/\.0$/,'')+' 秒';$('[data-bus-progress]').max=duration();$('[data-bus-progress]').value=elapsed;gearDown.disabled=!manual.checked||forcedGear===null||forcedGear<=1;gearUp.disabled=!manual.checked||forcedGear===null||forcedGear>=6;$('[data-selected-gear]').textContent=forcedGear===null?'自動':forcedGear+' 檔';target.disabled=style.disabled=manual.checked;root.dataset.active=String(playing);root.style.setProperty('--bus-vibration',condition.value==='poor'?'1.5px':condition.value==='good'?'.35px':'.75px');root.style.setProperty('--road-duration',Math.max(.25,6-state.speed*.12)+'s');$('[data-road]').dataset.moving=String(playing&&state.speed>.1);pause.disabled=!audio||(!playing&&!paused);pause.textContent=paused?'繼續':'暫停';stop.disabled=!audio;}
function schedule(now){if(!playing)return;const dt=Math.max(0,(now-last)/1000);last=now;if(manual.checked){state=manualStep(state,{rpm:Number(rpm.value),gear:forcedGear,throttle:Math.max(Number(gas.value)/100,held.gas),brake:Math.max(Number(brake.value)/100,held.brake)},dt);}else{elapsed=Math.min(duration(),elapsed+dt);if(elapsed>=duration()&&loop.checked)elapsed=0;state=cycleState(elapsed,options());}audio?.update(state,condition.value);display();frame=requestAnimationFrame(schedule);}
function release(){held={gas:0,brake:0};root.querySelectorAll('[data-pedal]').forEach(b=>b.setAttribute('aria-pressed','false'));}
async function halt(message='已停止。'){token++;playing=false;paused=false;cancelAnimationFrame(frame);release();const old=audio;audio=null;elapsed=0;state={...cycleState(0),rpm:0,frequency:0};display();status.textContent=message;delete root.dataset.audioBackend;start.disabled=false;await old?.close();}
start.addEventListener('click',async()=>{const id=++token;start.disabled=true;status.textContent='正在啟動音訊…';try{if(!audio)audio=new BusAudio();const current=audio;display();await current.init();if(id!==token)return;await current.resume();if(id!==token)return;root.dataset.audioBackend=current.worklet?'worklet':'compatibility';current.setVolume(Number(volume.value)/100);elapsed=0;state=cycleState(0,options());if(manual.checked){state={...state,rpm:Number(rpm.value),gear:forcedGear||1,frequency:Number(rpm.value)/20};}playing=true;paused=false;release();cancelAnimationFrame(frame);last=performance.now();audio.update(state,condition.value);frame=requestAnimationFrame(schedule);display();status.textContent=manual.checked?'手動模式已啟動。':'行車模擬已開始。';}catch(e){if(id===token){await halt('無法啟動音訊，請重試或更換支援 Web Audio 的瀏覽器。');console.error('Bus audio startup:',e.message);}}finally{if(id===token)start.disabled=false;}});
pause.addEventListener('click',async()=>{if(!audio)return;const current=audio,id=token;try{if(playing){playing=false;paused=true;cancelAnimationFrame(frame);release();await current.pause();if(id!==token||audio!==current)return;status.textContent='已暫停。';}else if(paused){await current.resume();if(id!==token||audio!==current)return;playing=true;paused=false;last=performance.now();frame=requestAnimationFrame(schedule);status.textContent='繼續行車。';}display();}catch{await halt('音訊已中斷，請重新開始。');}});
stop.addEventListener('click',()=>halt());manual.addEventListener('change',()=>{controls.disabled=!manual.checked;start.textContent=manual.checked?'啟動引擎':'開始行車模擬';loop.disabled=manual.checked;gas.value=brake.value='0';$('[data-gas-value]').textContent=$('[data-brake-value]').textContent='0%';halt('已切換模式，按下開始即可播放。');});
[target,style].forEach(input=>input.addEventListener('change',()=>halt('已更新行程，按下開始即可播放。')));
shiftMode.addEventListener('change',()=>{forcedGear=shiftMode.value==='manual'?state.gear:null;display();});
function shift(delta){if(!manual.checked||forcedGear===null)return;forcedGear=Math.max(1,Math.min(6,forcedGear+delta));state={...state,gear:forcedGear};display();}
gearDown.addEventListener('click',()=>shift(-1));gearUp.addEventListener('click',()=>shift(1));
volume.addEventListener('input',()=>{$('[data-volume-value]').textContent=volume.value+'%';audio?.setVolume(Number(volume.value)/100);});rpm.addEventListener('input',()=>{$('[data-rpm-value]').textContent=rpm.value+' RPM';});gas.addEventListener('input',()=>{$('[data-gas-value]').textContent=gas.value+'%';});brake.addEventListener('input',()=>{$('[data-brake-value]').textContent=brake.value+'%';});
root.querySelectorAll('[data-pedal]').forEach(b=>{const press=()=>{if(!manual.checked)return;held[b.dataset.pedal]=1;b.setAttribute('aria-pressed','true');},up=()=>{held[b.dataset.pedal]=0;b.setAttribute('aria-pressed','false');};b.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch{}press()});['pointerup','pointercancel','lostpointercapture','blur'].forEach(event=>b.addEventListener(event,up));b.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();press()}});b.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();up()}});});
document.addEventListener('visibilitychange',()=>{release();if(document.hidden&&playing){playing=false;paused=true;cancelAnimationFrame(frame);audio?.pause();display();status.textContent='離開頁面後已暫停，按下繼續即可播放。';}});window.addEventListener('blur',release);window.addEventListener('pagehide',()=>halt(''));state={...state,rpm:0,frequency:0};display();}
